/**
 * Typed loader for the gold-standard ABI fixtures in this directory
 * (`params.json`, `function.json`, `packed.json`, `events.json` —
 * regenerated by `node scripts/gen-abi-fixtures.mjs`).
 *
 * JSON-safe value conventions used by the fixture files:
 * - bigint → decimal string (revived here via `BigInt`)
 * - bytes / hashes → `0x…` hex string (kept as-is)
 * - address → TRON Base58 string (`T…`, kept as-is — both as encode input
 *   and as decode expectation)
 * - bool → boolean, arrays/tuples → nested JSON arrays (positional)
 * - `trcToken` → encoded like `uint256`, revives to bigint
 * - event `decoded`: object keyed by parameter name; indexed dynamic
 *   parameters hold their keccak256 topic (`0x…`) instead of the raw value
 * - function `result.decoded`: bare value for a single output, positional
 *   array for multiple outputs, `null` for no outputs
 */
import { readFileSync } from 'node:fs'

/** JSON-safe value as stored in the fixture files. */
export type FixtureValue = string | boolean | FixtureValue[]

/** Runtime value produced by {@link reviveValue}. */
export type RevivedValue = string | boolean | bigint | RevivedValue[]

/** Minimal ABI parameter shape used by the fixture files. */
export type FixtureParameter = {
  type: string
  name?: string
  components?: FixtureParameter[]
  indexed?: boolean
}

export type FixtureFunction = {
  type: 'function'
  name: string
  inputs: FixtureParameter[]
  outputs: FixtureParameter[]
  stateMutability: string
}

export type FixtureEvent = {
  type: 'event'
  name: string
  inputs: FixtureParameter[]
  anonymous: boolean
}

export type ParamsFixture = {
  name: string
  params: FixtureParameter[]
  values: FixtureValue[]
  encoded: `0x${string}`
}

export type FunctionFixture = {
  name: string
  abi: FixtureFunction[]
  functionName: string
  args: FixtureValue[]
  calldata: `0x${string}`
  result?: {
    returnData: `0x${string}`
    decoded: FixtureValue | null
  }
}

export type PackedFixture = {
  name: string
  types: string[]
  values: FixtureValue[]
  encoded: `0x${string}`
}

export type EventFixture = {
  name: string
  abi: FixtureEvent[]
  eventName: string
  args: FixtureValue[]
  topics: `0x${string}`[]
  data: `0x${string}`
  decoded: Record<string, FixtureValue>
}

/**
 * Revives a JSON-safe fixture value into its runtime form for the given ABI
 * parameter: decimal strings become bigints for `intN`/`uintN`/`trcToken`,
 * arrays and tuples recurse positionally, everything else (`address` in
 * `T…` form, `0x…` bytes, booleans, strings) passes through unchanged.
 */
export function reviveValue(
  param: FixtureParameter,
  value: FixtureValue,
): RevivedValue {
  const array = param.type.match(/^(.*)\[\d*\]$/)
  if (array) {
    if (!Array.isArray(value))
      throw new Error(`expected array value for ${param.type}`)
    return value.map((element) =>
      reviveValue({ ...param, type: array[1] as string }, element),
    )
  }
  if (param.type === 'tuple') {
    if (!Array.isArray(value))
      throw new Error('expected positional array value for tuple')
    return (param.components ?? []).map((component, i) =>
      reviveValue(component, value[i] as FixtureValue),
    )
  }
  if (param.type === 'trcToken' || /^u?int\d+$/.test(param.type))
    return BigInt(value as string)
  return value
}

/** Revives a positional list of values against its parameter list. */
export function reviveValues(
  params: readonly FixtureParameter[],
  values: readonly FixtureValue[],
): RevivedValue[] {
  return params.map((param, i) => reviveValue(param, values[i] as FixtureValue))
}

function readJson(fileName: string): unknown {
  return JSON.parse(readFileSync(new URL(fileName, import.meta.url), 'utf8'))
}

/** Cases for `encodeAbiParameters` / `decodeAbiParameters`. */
export function loadParamsFixtures(): ParamsFixture[] {
  return readJson('params.json') as ParamsFixture[]
}

/** Cases for `encodeFunctionData` / `decodeFunctionResult`. */
export function loadFunctionFixtures(): FunctionFixture[] {
  return readJson('function.json') as FunctionFixture[]
}

/** Cases for `encodePacked`. */
export function loadPackedFixtures(): PackedFixture[] {
  return readJson('packed.json') as PackedFixture[]
}

/** Cases for `encodeEventTopics` / `decodeEventLog`. */
export function loadEventFixtures(): EventFixture[] {
  return readJson('events.json') as EventFixture[]
}
